CREATE DATABASE IF NOT EXISTS noble_erp CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE noble_erp;
SET FOREIGN_KEY_CHECKS=0;
DROP TABLE IF EXISTS audit_logs,notifications,academic_calendar,assignment_submissions,assignments,results,marks,exam_attendance,exam_schedules,exams,fee_payments,student_fees,fee_structures,documents,leave_requests,attendance_records,attendance_sessions,timetables,enrollments,faculty_subjects,subjects,students,faculty,divisions,semesters,programs,users,role_permissions,permissions,roles,departments,institutions;
SET FOREIGN_KEY_CHECKS=1;
CREATE TABLE institutions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(180) NOT NULL,academic_year VARCHAR(20) NOT NULL,minimum_attendance DECIMAL(5,2) NOT NULL DEFAULT 75,logo_path VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE departments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,institution_id BIGINT UNSIGNED NOT NULL,name VARCHAR(150) NOT NULL,code VARCHAR(30) NOT NULL,active TINYINT(1) NOT NULL DEFAULT 1,UNIQUE KEY uq_dept(institution_id,code),FOREIGN KEY(institution_id) REFERENCES institutions(id) ON DELETE CASCADE,INDEX idx_dept_inst(institution_id));
CREATE TABLE roles(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(30) UNIQUE NOT NULL);
CREATE TABLE permissions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(80) UNIQUE NOT NULL,name VARCHAR(150) NOT NULL);
CREATE TABLE role_permissions(role_id BIGINT UNSIGNED NOT NULL,permission_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(role_id,permission_id),FOREIGN KEY(role_id) REFERENCES roles(id) ON DELETE CASCADE,FOREIGN KEY(permission_id) REFERENCES permissions(id) ON DELETE CASCADE);
CREATE TABLE users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,institution_id BIGINT UNSIGNED NOT NULL,department_id BIGINT UNSIGNED NULL,username VARCHAR(80) UNIQUE NOT NULL,email VARCHAR(180) UNIQUE NULL,student_id VARCHAR(80) UNIQUE NULL,faculty_id VARCHAR(80) UNIQUE NULL,name VARCHAR(180) NOT NULL,role ENUM('SUPER_ADMIN','ADMIN','HOD','FACULTY','STUDENT','PARENT') NOT NULL,password_hash VARCHAR(255) NOT NULL,active TINYINT(1) NOT NULL DEFAULT 1,last_login_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(institution_id) REFERENCES institutions(id) ON DELETE CASCADE,FOREIGN KEY(department_id) REFERENCES departments(id) ON DELETE SET NULL,INDEX idx_user_role(role),INDEX idx_user_inst(institution_id));
CREATE TABLE programs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,department_id BIGINT UNSIGNED NOT NULL,code VARCHAR(40) NOT NULL,name VARCHAR(150) NOT NULL,duration_years DECIMAL(3,1) NULL,degree_type VARCHAR(80) NULL,active TINYINT(1) DEFAULT 1,UNIQUE KEY uq_program(department_id,code),FOREIGN KEY(department_id) REFERENCES departments(id) ON DELETE CASCADE);
CREATE TABLE semesters(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,program_id BIGINT UNSIGNED NOT NULL,number INT NOT NULL,academic_year VARCHAR(20) NOT NULL,start_date DATE NULL,end_date DATE NULL,UNIQUE KEY uq_sem(program_id,number,academic_year),FOREIGN KEY(program_id) REFERENCES programs(id) ON DELETE CASCADE);
CREATE TABLE divisions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,semester_id BIGINT UNSIGNED NOT NULL,name VARCHAR(20) NOT NULL,capacity INT NULL,UNIQUE KEY uq_div(semester_id,name),FOREIGN KEY(semester_id) REFERENCES semesters(id) ON DELETE CASCADE);
CREATE TABLE students(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED UNIQUE NULL,enrollment_no VARCHAR(80) UNIQUE NOT NULL,admission_no VARCHAR(80) UNIQUE NULL,roll_no VARCHAR(30),first_name VARCHAR(80) NOT NULL,middle_name VARCHAR(80),last_name VARCHAR(80),gender VARCHAR(30),date_of_birth DATE,mobile VARCHAR(30),email VARCHAR(180),address TEXT,city VARCHAR(80),state VARCHAR(80),pincode VARCHAR(15),guardian_name VARCHAR(180),guardian_mobile VARCHAR(30),emergency_contact VARCHAR(30),blood_group VARCHAR(10),admission_date DATE,status ENUM('ACTIVE','INACTIVE','GRADUATED','SUSPENDED','TRANSFERRED','DROPOUT') DEFAULT 'ACTIVE',department_id BIGINT UNSIGNED,program_id BIGINT UNSIGNED,semester_id BIGINT UNSIGNED,division_id BIGINT UNSIGNED,academic_year VARCHAR(20),photo_path VARCHAR(255),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL,FOREIGN KEY(department_id) REFERENCES departments(id) ON DELETE SET NULL,FOREIGN KEY(program_id) REFERENCES programs(id) ON DELETE SET NULL,FOREIGN KEY(semester_id) REFERENCES semesters(id) ON DELETE SET NULL,FOREIGN KEY(division_id) REFERENCES divisions(id) ON DELETE SET NULL,INDEX idx_student_academic(department_id,program_id,semester_id,division_id),INDEX idx_student_status(status));
CREATE TABLE faculty(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED UNIQUE NULL,employee_code VARCHAR(80) UNIQUE NOT NULL,name VARCHAR(180) NOT NULL,email VARCHAR(180),mobile VARCHAR(30),designation VARCHAR(100),qualification VARCHAR(180),experience_years DECIMAL(4,1),joining_date DATE,status ENUM('ACTIVE','INACTIVE') DEFAULT 'ACTIVE',photo_path VARCHAR(255),department_id BIGINT UNSIGNED,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL,FOREIGN KEY(department_id) REFERENCES departments(id) ON DELETE SET NULL);
CREATE TABLE subjects(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,department_id BIGINT UNSIGNED NOT NULL,program_id BIGINT UNSIGNED NOT NULL,semester_id BIGINT UNSIGNED NOT NULL,code VARCHAR(50) NOT NULL,name VARCHAR(180) NOT NULL,credits INT DEFAULT 0,type ENUM('THEORY','PRACTICAL','BOTH') DEFAULT 'THEORY',internal_marks DECIMAL(6,2) DEFAULT 0,external_marks DECIMAL(6,2) DEFAULT 0,total_marks DECIMAL(6,2) DEFAULT 0,active TINYINT(1) DEFAULT 1,UNIQUE KEY uq_subject(semester_id,code),FOREIGN KEY(department_id) REFERENCES departments(id) ON DELETE CASCADE,FOREIGN KEY(program_id) REFERENCES programs(id) ON DELETE CASCADE,FOREIGN KEY(semester_id) REFERENCES semesters(id) ON DELETE CASCADE);
CREATE TABLE faculty_subjects(faculty_id BIGINT UNSIGNED NOT NULL,subject_id BIGINT UNSIGNED NOT NULL,PRIMARY KEY(faculty_id,subject_id),FOREIGN KEY(faculty_id) REFERENCES faculty(id) ON DELETE CASCADE,FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE CASCADE);
CREATE TABLE enrollments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,student_id BIGINT UNSIGNED NOT NULL,academic_year VARCHAR(20) NOT NULL,program_id BIGINT UNSIGNED,semester_id BIGINT UNSIGNED,division_id BIGINT UNSIGNED,roll_no VARCHAR(30),status ENUM('ACTIVE','COMPLETED','TRANSFERRED') DEFAULT 'ACTIVE',UNIQUE KEY uq_enroll(student_id,academic_year),FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE,FOREIGN KEY(program_id) REFERENCES programs(id) ON DELETE SET NULL,FOREIGN KEY(semester_id) REFERENCES semesters(id) ON DELETE SET NULL,FOREIGN KEY(division_id) REFERENCES divisions(id) ON DELETE SET NULL);
CREATE TABLE timetables(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,department_id BIGINT UNSIGNED,program_id BIGINT UNSIGNED,semester_id BIGINT UNSIGNED,division_id BIGINT UNSIGNED,subject_id BIGINT UNSIGNED,faculty_id BIGINT UNSIGNED,room VARCHAR(80),day_of_week TINYINT NOT NULL,start_time TIME NOT NULL,end_time TIME NOT NULL,active TINYINT(1) DEFAULT 1,FOREIGN KEY(department_id) REFERENCES departments(id) ON DELETE SET NULL,FOREIGN KEY(program_id) REFERENCES programs(id) ON DELETE SET NULL,FOREIGN KEY(semester_id) REFERENCES semesters(id) ON DELETE SET NULL,FOREIGN KEY(division_id) REFERENCES divisions(id) ON DELETE SET NULL,FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE SET NULL,FOREIGN KEY(faculty_id) REFERENCES faculty(id) ON DELETE SET NULL,INDEX idx_tt_day(day_of_week,start_time,end_time),INDEX idx_tt_faculty(faculty_id,day_of_week,start_time),INDEX idx_tt_room(room,day_of_week,start_time));
CREATE TABLE attendance_sessions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,timetable_id BIGINT UNSIGNED NOT NULL,faculty_id BIGINT UNSIGNED NOT NULL,subject_id BIGINT UNSIGNED NOT NULL,session_date DATE NOT NULL,UNIQUE KEY uq_att_session(timetable_id,session_date),FOREIGN KEY(timetable_id) REFERENCES timetables(id) ON DELETE CASCADE,FOREIGN KEY(faculty_id) REFERENCES faculty(id) ON DELETE RESTRICT,FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE RESTRICT);
CREATE TABLE attendance_records(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,session_id BIGINT UNSIGNED NOT NULL,student_id BIGINT UNSIGNED NOT NULL,status ENUM('PRESENT','ABSENT','LATE','EXCUSED') NOT NULL,marked_at DATETIME DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_att(session_id,student_id),FOREIGN KEY(session_id) REFERENCES attendance_sessions(id) ON DELETE CASCADE,FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE RESTRICT,INDEX idx_att_student(student_id,status));
CREATE TABLE leave_requests(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,applicant_user_id BIGINT UNSIGNED NOT NULL,student_id BIGINT UNSIGNED NULL,from_date DATE NOT NULL,to_date DATE NOT NULL,reason VARCHAR(255) NOT NULL,description TEXT,attachment_path VARCHAR(255),status ENUM('PENDING','APPROVED','REJECTED','CANCELLED') DEFAULT 'PENDING',approved_by BIGINT UNSIGNED NULL,approved_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(applicant_user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE SET NULL,FOREIGN KEY(approved_by) REFERENCES users(id) ON DELETE SET NULL,INDEX idx_leave_status(status));
CREATE TABLE fee_structures(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,institution_id BIGINT UNSIGNED NOT NULL,program_id BIGINT UNSIGNED,semester_id BIGINT UNSIGNED,name VARCHAR(150) NOT NULL,academic_year VARCHAR(20) NOT NULL,tuition_fee DECIMAL(12,2) DEFAULT 0,exam_fee DECIMAL(12,2) DEFAULT 0,library_fee DECIMAL(12,2) DEFAULT 0,lab_fee DECIMAL(12,2) DEFAULT 0,other_fee DECIMAL(12,2) DEFAULT 0,due_date DATE,active TINYINT(1) DEFAULT 1,FOREIGN KEY(institution_id) REFERENCES institutions(id) ON DELETE CASCADE,FOREIGN KEY(program_id) REFERENCES programs(id) ON DELETE SET NULL,FOREIGN KEY(semester_id) REFERENCES semesters(id) ON DELETE SET NULL);
CREATE TABLE student_fees(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,student_id BIGINT UNSIGNED NOT NULL,fee_structure_id BIGINT UNSIGNED NOT NULL,discount_amount DECIMAL(12,2) DEFAULT 0,scholarship_amount DECIMAL(12,2) DEFAULT 0,assigned_amount DECIMAL(12,2) NOT NULL,paid_amount DECIMAL(12,2) DEFAULT 0,due_date DATE,status ENUM('PENDING','PARTIAL','PAID','OVERDUE') DEFAULT 'PENDING',UNIQUE KEY uq_student_fee(student_id,fee_structure_id),FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE,FOREIGN KEY(fee_structure_id) REFERENCES fee_structures(id) ON DELETE RESTRICT);
CREATE TABLE fee_payments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,student_fee_id BIGINT UNSIGNED NOT NULL,receipt_no VARCHAR(80) UNIQUE NOT NULL,amount DECIMAL(12,2) NOT NULL,method VARCHAR(40) NOT NULL,reference VARCHAR(120),note VARCHAR(255),paid_at DATETIME DEFAULT CURRENT_TIMESTAMP,recorded_by BIGINT UNSIGNED NOT NULL,FOREIGN KEY(student_fee_id) REFERENCES student_fees(id) ON DELETE RESTRICT,FOREIGN KEY(recorded_by) REFERENCES users(id) ON DELETE RESTRICT);
CREATE TABLE exams(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,institution_id BIGINT UNSIGNED NOT NULL,name VARCHAR(180) NOT NULL,type ENUM('INTERNAL','MID_SEM','PRACTICAL','EXTERNAL','SEMESTER_END') NOT NULL,program_id BIGINT UNSIGNED,semester_id BIGINT UNSIGNED,start_date DATE,end_date DATE,status ENUM('DRAFT','PUBLISHED','COMPLETED') DEFAULT 'DRAFT',FOREIGN KEY(institution_id) REFERENCES institutions(id) ON DELETE CASCADE,FOREIGN KEY(program_id) REFERENCES programs(id) ON DELETE SET NULL,FOREIGN KEY(semester_id) REFERENCES semesters(id) ON DELETE SET NULL);
CREATE TABLE exam_schedules(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,exam_id BIGINT UNSIGNED NOT NULL,subject_id BIGINT UNSIGNED NOT NULL,division_id BIGINT UNSIGNED,exam_date DATE NOT NULL,start_time TIME NOT NULL,end_time TIME NOT NULL,room VARCHAR(80),instructions TEXT,UNIQUE KEY uq_exam_subject(exam_id,subject_id,division_id),FOREIGN KEY(exam_id) REFERENCES exams(id) ON DELETE CASCADE,FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE RESTRICT,FOREIGN KEY(division_id) REFERENCES divisions(id) ON DELETE SET NULL);
CREATE TABLE exam_attendance(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,schedule_id BIGINT UNSIGNED NOT NULL,student_id BIGINT UNSIGNED NOT NULL,status ENUM('PRESENT','ABSENT') NOT NULL,UNIQUE KEY uq_exam_att(schedule_id,student_id),FOREIGN KEY(schedule_id) REFERENCES exam_schedules(id) ON DELETE CASCADE,FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE RESTRICT);
CREATE TABLE marks(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,student_id BIGINT UNSIGNED NOT NULL,schedule_id BIGINT UNSIGNED NOT NULL,internal_marks DECIMAL(6,2) DEFAULT 0,external_marks DECIMAL(6,2) DEFAULT 0,practical_marks DECIMAL(6,2) DEFAULT 0,total_marks DECIMAL(6,2) DEFAULT 0,grade VARCHAR(5),gpa DECIMAL(4,2),pass_fail ENUM('PASS','FAIL') DEFAULT 'PASS',UNIQUE KEY uq_marks(student_id,schedule_id),FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE,FOREIGN KEY(schedule_id) REFERENCES exam_schedules(id) ON DELETE CASCADE);
CREATE TABLE results(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,student_id BIGINT UNSIGNED NOT NULL,exam_id BIGINT UNSIGNED NOT NULL,percentage DECIMAL(6,2),gpa DECIMAL(4,2),cgpa DECIMAL(4,2),backlog_count INT DEFAULT 0,status ENUM('DRAFT','PUBLISHED') DEFAULT 'DRAFT',published_at DATETIME NULL,UNIQUE KEY uq_result(student_id,exam_id),FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE,FOREIGN KEY(exam_id) REFERENCES exams(id) ON DELETE CASCADE);
CREATE TABLE assignments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,faculty_id BIGINT UNSIGNED NOT NULL,subject_id BIGINT UNSIGNED NOT NULL,title VARCHAR(180) NOT NULL,description TEXT,attachment_path VARCHAR(255),deadline DATETIME,max_marks DECIMAL(8,2),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(faculty_id) REFERENCES faculty(id) ON DELETE CASCADE,FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE RESTRICT);
CREATE TABLE assignment_submissions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,assignment_id BIGINT UNSIGNED NOT NULL,student_id BIGINT UNSIGNED NOT NULL,file_path VARCHAR(255),submitted_at DATETIME DEFAULT CURRENT_TIMESTAMP,marks DECIMAL(8,2) NULL,feedback TEXT,UNIQUE KEY uq_submission(assignment_id,student_id),FOREIGN KEY(assignment_id) REFERENCES assignments(id) ON DELETE CASCADE,FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE);
CREATE TABLE documents(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,student_id BIGINT UNSIGNED,faculty_id BIGINT UNSIGNED,type VARCHAR(80) NOT NULL,name VARCHAR(180) NOT NULL,file_path VARCHAR(255) NOT NULL,status ENUM('PENDING','APPROVED','REJECTED') DEFAULT 'PENDING',review_note VARCHAR(255),uploaded_by BIGINT UNSIGNED,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE,FOREIGN KEY(faculty_id) REFERENCES faculty(id) ON DELETE CASCADE,FOREIGN KEY(uploaded_by) REFERENCES users(id) ON DELETE SET NULL,INDEX idx_doc_student(student_id,status));
CREATE TABLE notifications(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,title VARCHAR(180) NOT NULL,message TEXT NOT NULL,type VARCHAR(50),is_read TINYINT(1) DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,INDEX idx_notification(user_id,is_read,created_at));
CREATE TABLE academic_calendar(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,institution_id BIGINT UNSIGNED NOT NULL,title VARCHAR(180) NOT NULL,type VARCHAR(50),start_date DATE NOT NULL,end_date DATE NULL,description TEXT,FOREIGN KEY(institution_id) REFERENCES institutions(id) ON DELETE CASCADE);
CREATE TABLE audit_logs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NULL,action VARCHAR(80) NOT NULL,module VARCHAR(80) NOT NULL,record_id BIGINT UNSIGNED NULL,ip_address VARCHAR(45),metadata JSON NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL,INDEX idx_audit(module,record_id,created_at),INDEX idx_audit_user(user_id,created_at));
INSERT INTO roles(name) VALUES('SUPER_ADMIN'),('ADMIN'),('HOD'),('FACULTY'),('STUDENT'),('PARENT') ON DUPLICATE KEY UPDATE name=VALUES(name);
